package kr.co.donationserver.command;
import kr.co.donationserver.config.ModConfig;import kr.co.donationserver.data.*;import kr.co.donationserver.util.Texts;import net.minecraft.command.*;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.server.MinecraftServer;import java.util.*;
public class DonationStatusCommand extends PublicPlayerCommand {public String getName(){return "기부현황";}public int getRequiredPermissionLevel(){return 0;}public List<String> getAliases(){return Collections.singletonList("donationstatus");}public String getUsage(ICommandSender s){return "/기부현황";}public void execute(MinecraftServer server,ICommandSender sender,String[] args)throws CommandException{EntityPlayerMP p=getCommandSenderAsPlayer(sender);DonationData d=DonationData.get(p.world);PlayerData pd=d.player(p.getUniqueID());p.sendMessage(Texts.text("&6서버 기부: &f"+Texts.money(d.serverTotal)+" / "+Texts.money(ModConfig.goal)));p.sendMessage(Texts.text("&6내 기부: &f"+Texts.money(pd.donation)+"  &6잔액: &f"+Texts.money(pd.balance)));}}
